"""Browser control page for the currently running simulation."""
LIVE_HTML = r'''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SkyFleet 即時控制</title><style>
body{margin:0;background:#101b2b;color:#e6f0f9;font:14px system-ui}header,form{padding:14px;background:#1b2c42}h1{font-size:21px;margin:0 0 5px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:12px;padding:12px}canvas{display:block;width:100%;height:70vh;min-height:460px;background:#162738;border-radius:8px}aside{background:#1b2c42;border-radius:8px;overflow:auto}label{display:block;margin:12px 0}input{background:#102237;color:#fff;border:1px solid #617c92;padding:8px;border-radius:4px}input[type=number]{width:70px}button{background:#3c9ab6;color:#081928;border:0;border-radius:4px;padding:9px;cursor:pointer;font-weight:bold}#drones label{margin:5px 0}#status,#topology{padding:12px;white-space:pre-wrap}small{color:#a9bed0}@media(max-width:750px){.layout{grid-template-columns:1fr}}
</style><header><h1>SkyFleet · 運行中派遣</h1><small>3D MuJoCo 為主展示視窗；此頁僅作控制台。點地圖填入 X/Y 或手動輸入座標；L 是本地指令，R/S 經無線接收後生效。</small></header><div class="layout"><canvas id="map"></canvas><aside><form id="dispatch"><strong>派遣編隊</strong><div id="drones"></div><label>目標 X <input type="number" id="x" value="50" step="any"> Y <input type="number" id="y" value="92" step="any"> Z <input type="number" id="z" value="30" step="any"></label><label>分組 <input id="group" value="east"></label><button>發送適應性編隊指令</button></form><div id="status"></div><div id="topology"></div></aside></div><script>
const canvas=document.querySelector('canvas'),ctx=canvas.getContext('2d'),checks=document.getElementById('drones');let state=null,mapTransform=null,chosen=null;
function paint(s){let W=canvas.width=canvas.clientWidth*devicePixelRatio,H=canvas.height=canvas.clientHeight*devicePixelRatio;ctx.scale(devicePixelRatio,devicePixelRatio);W=canvas.clientWidth;H=canvas.clientHeight;
let pts=Object.values(s.nodes).map(n=>n.pos),bounds=s.buildings.flatMap(([x,y,w,d])=>[[x,y],[x+w,y+d]]);let xx=pts.map(p=>p[0]).concat(bounds.map(p=>p[0])),yy=pts.map(p=>p[1]).concat(bounds.map(p=>p[1]));let minX=Math.min(...xx,0)-15,maxX=Math.max(...xx,100)+15,minY=Math.min(...yy,0)-15,maxY=Math.max(...yy,100)+15;let scale=Math.min((W-30)/(maxX-minX),(H-30)/(maxY-minY)),px=x=>15+(x-minX)*scale,py=y=>H-15-(y-minY)*scale;
mapTransform={minX,minY,H,scale};
ctx.fillStyle='#162738';ctx.fillRect(0,0,W,H);for(const [x,y,w,d,h] of s.buildings){ctx.fillStyle='#526b7e';ctx.fillRect(px(x),py(y+d),w*scale,d*scale);ctx.fillStyle='#e6f0f9';ctx.fillText(h+'m',px(x)+3,py(y+d)+13)}
for(const [a,b] of s.edges){let p=s.nodes[a].pos,q=s.nodes[b].pos;ctx.beginPath();ctx.moveTo(px(p[0]),py(p[1]));ctx.lineTo(px(q[0]),py(q[1]));ctx.strokeStyle='#50bb8f';ctx.globalAlpha=.45;ctx.stroke();ctx.globalAlpha=1}
for(const [id,n] of Object.entries(s.nodes)){ctx.beginPath();ctx.arc(px(n.pos[0]),py(n.pos[1]),n.role==='LEADER'?7:5,0,7);ctx.fillStyle=n.role==='LEADER'?'#fb7171':n.group==='main'?'#62d3ee':'#f8ba5b';ctx.fill();ctx.fillStyle='#fff';ctx.fillText(id+' '+n.formation,px(n.pos[0])+8,py(n.pos[1])-7)}
if(chosen){ctx.beginPath();ctx.arc(px(chosen[0]),py(chosen[1]),9,0,Math.PI*2);ctx.strokeStyle='#ffcf5a';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#ffcf5a';ctx.fillText('目的地',px(chosen[0])+12,py(chosen[1])-10)}
}
canvas.addEventListener('click',e=>{if(!mapTransform||!state||!state.running)return;const rect=canvas.getBoundingClientRect(),{minX,minY,H,scale}=mapTransform;const x=minX+(e.clientX-rect.left-15)/scale,y=minY+(H-15-(e.clientY-rect.top))/scale;chosen=[x,y];document.getElementById('x').value=x.toFixed(2);document.getElementById('y').value=y.toFixed(2);paint(state)});
async function update(){try{let s=await (await fetch('/api/state',{cache:'no-store'})).json();state=s;if(Object.keys(s.nodes).length){paint(s);let selected=new Set([...checks.querySelectorAll('input:checked')].map(i=>i.value));checks.replaceChildren(...Object.entries(s.nodes).filter(([id,n])=>['LEADER','RELAY','SLAVE'].includes(n.role)).map(([id])=>{let row=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.value=id;box.checked=selected.has(id);row.append(box,document.createTextNode(' '+id+' · '+s.nodes[id].group+' · '+s.nodes[id].formation));return row}))}document.getElementById('topology').textContent='仿真 '+s.t+' / '+s.duration+' s · '+(s.running?'運行中':'已結束')+'\n通信連通分量：'+s.components.map(c=>c.join(', ')).join(' | ')}catch(e){document.getElementById('status').textContent=e.message}}
setInterval(update,250);update();document.getElementById('dispatch').onsubmit=async e=>{e.preventDefault();let nodes=[...checks.querySelectorAll('input:checked')].map(i=>i.value),destination=['x','y','z'].map(id=>Number(document.getElementById(id).value));let reply=await fetch('/api/dispatch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({nodes,destination,group:document.getElementById('group').value})});let body=await reply.json();document.getElementById('status').textContent=reply.ok?'已排入指令：'+body.queued.join(', '):body.error};
</script></html>'''

# Native MuJoCo remains the only 3D view; the canvas is a dispatch aid.
NATIVE_CONTROL_HTML = r'''<!doctype html><html lang="zh-Hans"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SkyFleet 原生 3D 控制台</title>
<style>
body{font:15px system-ui;background:#122033;color:#e9f2ff;margin:20px auto;max-width:1180px;padding:0 16px}h1{margin:0 0 8px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:16px}.map-panel,.control-panel{background:#192c42;border-radius:10px;padding:14px}#minimap{width:100%;height:520px;display:block;background:#102237;cursor:crosshair;border-radius:6px;touch-action:none}label{display:block;margin:9px 0}input{padding:7px;background:#22374e;border:1px solid #879eb3;color:#fff;border-radius:4px}input[type=number]{width:75px}input[type=range]{width:220px;vertical-align:middle}button{padding:10px 20px;background:#50c5ae;border:0;border-radius:5px;cursor:pointer;font-weight:700}#nodes{display:grid;grid-template-columns:repeat(3,1fr)}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px system-ui}small{color:#bbcedd}@media(max-width:800px){.layout{grid-template-columns:1fr}#minimap{height:400px}}
</style>
<h1>SkyFleet · MuJoCo 3D 控制台</h1><p>原生 MuJoCo 窗口仍是主 3D 画面；左侧俯视图点击选点，右侧调高度，黄色球同步预览。L 本地控制；R/S 需经 ns-3 接收后才执行。</p>
<div class="layout"><section class="map-panel"><strong>2D 俯视迷你调度图</strong><p><small>建筑轮廓 · 无人机实时位置 · 点击地图选择目标 X/Y</small></p><canvas id="minimap" aria-label="俯视调度图"></canvas><small id="map-coordinates">点击地图选点</small></section><section class="control-panel"><form id="dispatch"><strong>选择飞机与目标</strong><div id="nodes"></div><label>X <input type="number" id="x" step="any" value="50"> Y <input type="number" id="y" step="any" value="75"></label><label>Z 高度 <input type="range" id="z-slider" min="0" max="300" step="1" value="30"> <input type="number" id="z" step="any" value="30"> m</label><label>编组 <input id="group" value="east"></label><button>发送自适应编队指令</button></form><pre id="status"></pre><small>原生窗口：双击机身选机；1/2/3/0 快选；F 相机焦点预览，[ / ] 调高度，Enter 派遣，Esc 取消。</small></section></div>
<script>
const canvas=document.getElementById('minimap'),ctx=canvas.getContext('2d'),box=document.getElementById('nodes');
const xInput=document.getElementById('x'),yInput=document.getElementById('y'),zInput=document.getElementById('z'),slider=document.getElementById('z-slider');
let state=null,transform=null,preview=null,previewTimer=null,previewVersion=0,previewPending=false,previewBusy=false,previewQueued=undefined,previewDrain=Promise.resolve(),submitting=false;
function coordinates(){return [Number(xInput.value),Number(yInput.value),Number(zInput.value)]}
async function sendPreview(destination){if(submitting)return;previewQueued=destination;const version=++previewVersion;if(previewBusy)return;previewBusy=true;previewDrain=(async()=>{try{do{const next=previewQueued,requestVersion=previewVersion;previewQueued=undefined;try{const reply=await fetch('/api/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({destination:next})});const data=await reply.json();if(!reply.ok&&requestVersion===previewVersion){previewPending=false;document.getElementById('status').textContent=data.error}}catch(err){if(requestVersion===previewVersion)document.getElementById('status').textContent=String(err)}}while(previewQueued!==undefined)}finally{previewBusy=false}})();return previewDrain}
function updatePreview(){const p=coordinates();if(p.every(Number.isFinite)){preview=p;previewPending=true;document.getElementById('map-coordinates').textContent=`预览 X ${p[0].toFixed(1)} · Y ${p[1].toFixed(1)} · Z ${p[2].toFixed(1)} m`;paint();clearTimeout(previewTimer);previewTimer=setTimeout(()=>{sendPreview(p)},80)}}
function paint(){if(!state)return;const width=canvas.clientWidth,height=canvas.clientHeight,dpr=window.devicePixelRatio||1;canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#102237';ctx.fillRect(0,0,width,height);
const points=Object.values(state.nodes).map(n=>n.pos),corners=state.buildings.flatMap(([x,y,w,d])=>[[x,y],[x+w,y+d]]),all=points.concat(corners);if(!all.length)return;
const minX=Math.min(0,...all.map(p=>p[0]))-15,maxX=Math.max(100,...all.map(p=>p[0]))+15,minY=Math.min(0,...all.map(p=>p[1]))-15,maxY=Math.max(100,...all.map(p=>p[1]))+15;
const scale=Math.min((width-30)/(maxX-minX),(height-30)/(maxY-minY)),left=(width-(maxX-minX)*scale)/2,top=(height-(maxY-minY)*scale)/2;
const px=x=>left+(x-minX)*scale,py=y=>height-top-(y-minY)*scale;transform={left,top,minX,minY,scale,width,height};
for(const [x,y,w,d,h] of state.buildings){ctx.fillStyle='#536b7c';ctx.fillRect(px(x),py(y+d),w*scale,d*scale);ctx.fillStyle='#edf5fb';ctx.font='11px system-ui';ctx.fillText(`${h}m`,px(x)+3,py(y+d)+12)}
for(const [a,b] of state.radio_links||[]){const p=state.nodes[a]?.pos,q=state.nodes[b]?.pos;if(!p||!q)continue;ctx.beginPath();ctx.moveTo(px(p[0]),py(p[1]));ctx.lineTo(px(q[0]),py(q[1]));ctx.strokeStyle='#40d8a4';ctx.stroke()}
for(const [id,node] of Object.entries(state.nodes)){const [x,y]=node.pos;ctx.beginPath();ctx.arc(px(x),py(y),id==='L'?7:5,0,2*Math.PI);ctx.fillStyle=id==='L'?'#ff786c':id.startsWith('R')?'#ffb766':'#67c9fa';ctx.fill();if((state.selected||[]).includes(id)){ctx.strokeStyle='#ffd65e';ctx.lineWidth=2;ctx.stroke()}ctx.fillStyle='#fff';ctx.font='12px system-ui';ctx.fillText(id,px(x)+9,py(y)-6)}
if(preview){ctx.beginPath();ctx.arc(px(preview[0]),py(preview[1]),9,0,2*Math.PI);ctx.strokeStyle='#ffd65e';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#ffd65e';ctx.fillText('目标',px(preview[0])+12,py(preview[1])-8)}}
canvas.addEventListener('click',event=>{if(!transform||!state?.running)return;const rect=canvas.getBoundingClientRect(),t=transform;const cx=(event.clientX-rect.left)*t.width/rect.width,cy=(event.clientY-rect.top)*t.height/rect.height;xInput.value=(t.minX+(cx-t.left)/t.scale).toFixed(2);yInput.value=(t.minY+(t.height-t.top-cy)/t.scale).toFixed(2);updatePreview()});
for(const input of [xInput,yInput,zInput])input.addEventListener('input',()=>{if(input===zInput&&Number.isFinite(Number(zInput.value)))slider.value=zInput.value;updatePreview()});slider.addEventListener('input',()=>{zInput.value=slider.value;updatePreview()});window.addEventListener('resize',paint);
async function poll(){try{const s=await(await fetch('/api/state',{cache:'no-store'})).json();state=s;if(Number(box.dataset.version??-1)<Number(s.selection_version??0)){box.dataset.version=String(s.selection_version);box.dataset.selected=JSON.stringify(s.selected||[])}const chosen=new Set(JSON.parse(box.dataset.selected||'[]'));if(!previewPending&&previewQueued===undefined&&!previewBusy)preview=s.preview||null;else if(JSON.stringify(preview)===JSON.stringify(s.preview))previewPending=false;box.replaceChildren(...Object.entries(s.nodes).map(([id,node])=>{const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.value=id;input.checked=chosen.has(id);input.onchange=async()=>{const nodes=[...box.querySelectorAll('input:checked')].map(x=>x.value);box.dataset.selected=JSON.stringify(nodes);const reply=await fetch('/api/selection',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({nodes})});if(!reply.ok){box.dataset.version='';await poll()}};label.append(input,document.createTextNode(' '+id+' · '+node.formation+' · '+node.group));return label}));paint();document.getElementById('status').textContent='t='+s.t+'s / '+s.duration+'s  '+(s.running?'运行中':'结束')+'\n最近 ns-3 接收跳段: '+JSON.stringify(s.radio_links||[])+'\n'+(s.error||'')}catch(err){document.getElementById('status').textContent=String(err)}}
setInterval(poll,300);poll();document.getElementById('dispatch').onsubmit=async event=>{event.preventDefault();submitting=true;clearTimeout(previewTimer);previewQueued=undefined;const nodes=[...document.querySelectorAll('#nodes input:checked')].map(x=>x.value),destination=coordinates();try{await previewDrain;const result=await fetch('/api/dispatch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({nodes,destination,group:document.getElementById('group').value})});const data=await result.json();document.getElementById('status').textContent=result.ok?'已排入 '+data.queued.join(', '):data.error;if(result.ok){clearTimeout(previewTimer);previewQueued=undefined;previewPending=true;preview=null;paint()}}catch(err){document.getElementById('status').textContent=String(err)}finally{submitting=false}};
</script></html>'''
